import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-11-06 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2019-11-06 :: Ceph Developer Monthly","date":"2019-11-06T00:00:00.000Z","updated":"2019-11-07T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson 项目","小对象存储优化","瞬时挂载","分布式重复数据删除","崩溃报告"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-06_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2019/2019-11-06_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-11-06_-_-_Ceph_Developer_Monthly.md"};function a(n,l,s,p,_,h){return i(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 未知（会议记录中未提及所有参会人员姓名）</p><p><strong>会议主题</strong>：</p><ul><li>Crimson 项目更新</li><li>小对象存储优化</li><li>瞬时挂载更新</li><li>分布式重复数据删除（Dee Dup）项目状态</li><li>统计信息和崩溃报告</li></ul><h3 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h3><p><strong>1. Crimson 项目更新</strong></p><ul><li>Crimson 项目旨在提高 Ceph 的计算效率，减少开销。</li><li>项目已进行了一年以上，目前处于功能完善阶段。</li><li>Crimson 管理器已实现与现有异步管理器的通信，并支持 v2 协议。</li><li>对象存储组件目前使用内存存储进行原型设计，后续将移植 Blue Store。</li></ul><p><strong>2. 小对象存储优化</strong></p><ul><li>小对象存储在空间利用方面存在开销，需要优化。</li><li>讨论了减少最小分配大小、使用 RocksDB 存储小对象、优化对象存储接口等方法。</li><li>认为将小对象存储在复制池中可能是一个解决方案。</li></ul><p><strong>3. 瞬时挂载更新</strong></p><ul><li>瞬时挂载（Export Ephemeral Pinning）旨在优化元数据分布。</li><li>使用一致哈希算法实现元数据的随机和分布式分区。</li><li>讨论了基准测试方案，包括权威子树数量、MDS 热度因子、跨 MDS 操作等。</li></ul><p><strong>4. 分布式重复数据删除（Dee Dup）项目状态</strong></p><ul><li>Dee Dup 项目旨在通过内容地址存储和引用计数实现重复数据删除。</li><li>项目已完成了大部分基础设施和基本功能，目前处于完善和测试阶段。</li><li>讨论了使用外部工具测试 Dee Dup 的工作流程，并希望获得用户反馈。</li></ul><p><strong>5. 统计信息和崩溃报告</strong></p><ul><li>Ceph 现在可以收集崩溃报告，并将其发送到上游实验室。</li><li>崩溃报告包含堆栈跟踪、版本信息和崩溃签名等信息。</li><li>讨论了如何将崩溃签名与跟踪器中的问题关联起来，并优先处理。</li><li>讨论了如何改进崩溃报告的收集和展示方式。</li></ul><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ul><li>继续推进 Crimson 项目，完善功能并进行测试。</li><li>优化小对象存储，减少空间开销。</li><li>完善瞬时挂载功能，并进行基准测试。</li><li>完善 Dee Dup 项目，并进行用户测试。</li><li>改进崩溃报告的收集和展示方式。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>项目负责人将创建 Trello 卡片，跟踪各项任务的进度。</li><li>邀请更多开发者参与讨论和开发。</li><li>发布相关文档，提供技术支持。</li></ul>',20)])])}const c=e(r,[["render",a]]);export{d as __pageData,c as default};
